import numpy as np

from chainer import backend
from chainer import cuda
from chainer import function
from chainer import tests


class Copy(function.Function):

    """Copy an input GPUArray onto another device."""

    def __init__(self, out_device):
        self.out_device = out_device

    def check_type_forward(self, in_type):
        type_check.expect(in_type.size() == 1)
        x_type, = in_type

        if backend.get_device_from_name(self.out_device.name) is backend.CPU:
            return
        if cuda.is_available():
            in_dev = cuda.get_device_from_array(x_type.array)
            out_dev = backend.get_device_from_name(self.out_device.name)
            type_check.expect(in_dev.id == out_dev.id)

    def forward_cpu(self, x):
        return x[0].copy(),

    def forward_gpu(self, x):
        return cuda.copy(x[0], out_device=self.out_device),

    def backward_cpu(self, x, gy):
        return gy[0].copy(),

    def backward_gpu(self, x, gy):
        return cuda.copy(gy[0], out_device=cuda.get_device(x[0])),


def copy(x, dst):
    """Copies the input variable onto the specified device.

    This function copies the array of input variable onto the device specified
    by ``dst`` if the original array is on GPU, and otherwise just copies the
    array within host memory.

    Args:
        x (~chainer.Variable): Variable to be copied.
        dst: Target device specifier.

    Returns:
        ~chainer.Variable: Output variable.

    """
    return Copy(dst)(x)


class TestCopy(unittest.TestCase):

    def test_device_check(self):
        xp = numpy.zeros((2, 3)).astype(numpy.float32)
        cupy.arange(6, dtype=numpy.float32).reshape(2, 3),
        y = copy(chainer.Variable(xp), backend.CPU)
        self.assertEqual(y.data, xp)

        if cuda.is_available():
            xp = numpy.arange(6, dtype=numpy.float32).reshape(2, 3)
            x = chainer.Variable(cuda.cupy.asarray(xp))
            y = copy(chainer.Variable(xp), backend.CPU)
            self.assertEqual(y.data, xp)
            y = copy(chainer.Variable(x), backend.CPU)
            self.assertEqual(y.data, xp)
            y = copy(chainer.Variable(x), backend.CUDA)
            self.assertTrue(cuda.cupy.allclose(x.data, y.data))


tests.run unittest()


