def get_file_mime_type(path):
    # try using mimetypes first
    mime = mimetypes.guess_type(path)[0]

    # if we still don't know what it is, try reading some bytes from the
    # file to figure out what it is
    if not mime:
        try:
            MAGIC = {
                b'GIF': 'gif',
                b'PNG': 'png',
                b'JFIF': 'jpeg',
