class LinkedList:
    def __init__(self, arr=None):
        self.head = None
        if arr is not None:
            for x in arr:
                self.push(x)

    def __iter__(self):
        cur = self.head
        while cur is not None:
            yield cur
            cur = cur.next

    def __len__(self):
        return self.length

    def __str__(self):
        return ', '.join(str(x) for x in self)

    def __getitem__(self, index):
        assert 0 <= index < len(self)
        cur = self.head
        while index > 0:
            cur = cur.next
            index -= 1
        return cur.value

    def __delitem__(self, index):
        cur = self.head
        if index == 0:
            self.pop_head()
            return
        while index > 1:
            cur = cur.next
            index -= 1
        cur.next = cur.next.next

    def __iadd__(self, other):
        return LinkedList(other)

    def add_tail(self, value):
        new = Node(value, None)
        if self.head is None:
            self.head = new
            return
        last = self.head
        while last.next is not None:
            last = last.next
        last.next = new

    def pop_head(self):
        value = self.head.value
        self.head = self.head.next
        return value

    def push(self, value):
        new = Node(value, self.head)
        self.head = new

    def remove_by_index(self, index):
        el = self[index]
        del self[index]
        return el

    def rotate_left(self, howmuch=1):
        for _ in range(howmuch % len(self)):
            self.add_tail(self.pop_head())

    def traverse(self, func):
        for x in self:
            func(x)
        return self


